// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetDemoChallenge A proof-of-work challenge for one demo run (no account needed)
	// (GET /demo/challenge)
	GetDemoChallenge(w http.ResponseWriter, r *http.Request)
	// RunDemo Run a sample helper without an account (Test mode, nothing saved or sent)
	// (POST /demo/runs)
	RunDemo(w http.ResponseWriter, r *http.Request)
	// GetFeedCard A Feed card, with the cards it asks about (Check first, Let me pick)
	// (GET /feed-cards/{feedCardId})
	GetFeedCard(w http.ResponseWriter, r *http.Request, feedCardId FeedCardId)
	// DecideFeedCard Answer an Ask me card; the waiting run goes on
	// (POST /feed-cards/{feedCardId}/decision)
	DecideFeedCard(w http.ResponseWriter, r *http.Request, feedCardId FeedCardId)
	// DismissFeedCard Hide a Result or Problem card (or a decided or expired one) from the Feed
	// (POST /feed-cards/{feedCardId}/dismiss)
	DismissFeedCard(w http.ResponseWriter, r *http.Request, feedCardId FeedCardId)
	// GetHealth Service health
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// DeleteHelper Delete a helper with its runs and Feed cards
	// (DELETE /helpers/{helperId})
	DeleteHelper(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// GetHelper A helper with its bricks in plain words and its recent runs
	// (GET /helpers/{helperId})
	GetHelper(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// UpdateHelper Rename a helper, or switch it on or off
	// (PATCH /helpers/{helperId})
	UpdateHelper(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// ForgetLearned Forget what the helper learned from Let me pick swipes
	// (DELETE /helpers/{helperId}/learned)
	ForgetLearned(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// StartRun Run a helper now (Tap Go, or a test run with at most 3 cards)
	// (POST /helpers/{helperId}/runs)
	StartRun(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// GetHelperStack A helper's current stack for the builder, with what each brick gave last time
	// (GET /helpers/{helperId}/stack)
	GetHelperStack(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// SaveHelperStack Save an edited stack as the helper's next version
	// (PUT /helpers/{helperId}/stack)
	SaveHelperStack(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// TestHelperStack Test an edited stack once (max 3 cards) without making it the helper's version
	// (POST /helpers/{helperId}/stack/test)
	TestHelperStack(w http.ResponseWriter, r *http.Request, helperId HelperId)
	// DeleteList Delete a list with all its rows (owner only). Helpers that save to it stop with a note until you pick another list
	// (DELETE /lists/{listId})
	DeleteList(w http.ResponseWriter, r *http.Request, listId ListId)
	// GetList A list with its rows (at most 500 that match)
	// (GET /lists/{listId})
	GetList(w http.ResponseWriter, r *http.Request, listId ListId, params GetListParams)
	// UpdateList Rename a list
	// (PATCH /lists/{listId})
	UpdateList(w http.ResponseWriter, r *http.Request, listId ListId)
	// ExportList All rows as a CSV file (UTF-8, comma separated, header row)
	// (GET /lists/{listId}/csv)
	ExportList(w http.ResponseWriter, r *http.Request, listId ListId)
	// AddListRows Add cards from a Feed card to a list ("Add to list"). Duplicates (same website, email or name) are skipped
	// (POST /lists/{listId}/rows)
	AddListRows(w http.ResponseWriter, r *http.Request, listId ListId)
	// DeleteListRow Delete one row
	// (DELETE /lists/{listId}/rows/{rowId})
	DeleteListRow(w http.ResponseWriter, r *http.Request, listId ListId, rowId openapi_types.UUID)
	// UnshareList Turn the share link off; the old link stops working (owner only)
	// (DELETE /lists/{listId}/share)
	UnshareList(w http.ResponseWriter, r *http.Request, listId ListId)
	// ShareList Turn on the read-only share link (owner only). Anyone with the link can see the rows
	// (PUT /lists/{listId}/share)
	ShareList(w http.ResponseWriter, r *http.Request, listId ListId)
	// GetMe The signed-in user and their workspaces
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// DeletePlace Remove a chat (owner only). Helpers that post there stop with a note in the Feed until you pick another chat
	// (DELETE /places/{placeId})
	DeletePlace(w http.ResponseWriter, r *http.Request, placeId PlaceId)
	// TestPlace Send a test message to a chat
	// (POST /places/{placeId}/test)
	TestPlace(w http.ResponseWriter, r *http.Request, placeId PlaceId)
	// GetSharedList A list someone shared, read-only. No sign-in needed
	// (GET /shared/lists/{token})
	GetSharedList(w http.ResponseWriter, r *http.Request, token string)
	// CreateWorkspace Create a workspace (you become its owner)
	// (POST /workspaces)
	CreateWorkspace(w http.ResponseWriter, r *http.Request)
	// GetWorkspace One of your workspaces
	// (GET /workspaces/{workspaceId})
	GetWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UpdateWorkspace Change name, timezone, language or About me facts (owner only)
	// (PATCH /workspaces/{workspaceId})
	UpdateWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListFeed The Feed, newest first, with the Needs me count and the brain allowance
	// (GET /workspaces/{workspaceId}/feed)
	ListFeed(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListFeedParams)
	// ListHelpers Your helpers, newest first
	// (GET /workspaces/{workspaceId}/helpers)
	ListHelpers(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreateHelper Make a helper from a Shelf template, optionally running a test right away
	// (POST /workspaces/{workspaceId}/helpers)
	CreateHelper(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListLists Your Lists (businesses, leads, links that helpers saved)
	// (GET /workspaces/{workspaceId}/lists)
	ListLists(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreateList Start an empty list
	// (POST /workspaces/{workspaceId}/lists)
	CreateList(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListPlaces Where your helpers can tell you things (chats)
	// (GET /workspaces/{workspaceId}/places)
	ListPlaces(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreatePlace Connect a chat. Sends a test message first; only a chat that got it is saved (owner only)
	// (POST /workspaces/{workspaceId}/places)
	CreatePlace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListTemplates The Shelf, sorted by your needs, in your language, with known About me facts filled in
	// (GET /workspaces/{workspaceId}/templates)
	ListTemplates(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// GetDemoChallenge operation middleware
func (siw *ServerInterfaceWrapper) GetDemoChallenge(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.GetDemoChallenge(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// RunDemo operation middleware
func (siw *ServerInterfaceWrapper) RunDemo(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.RunDemo(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

